perf.naive:
def lap_start(charge: list[int], drain: list[int]) -> int:
    n = len(charge)
    for start in range(n):               # simulate the lap from every station
        battery = 0
        for k in range(n):
            i = (start + k) % n
            battery += charge[i] - drain[i]
            if battery < 0:
                break
        else:
            return start
    return -1
